export function getT(dict, lang, defaultLang = 'en-US') {
  if (!dict) return '';
  if (!lang || typeof lang !== 'string') return dict['en-US'] !== undefined ? dict['en-US'] : (dict['ja-JP'] || '');
  if (dict[lang] !== undefined) return dict[lang];
  const shortLang = lang.split('-')[0];
  if (dict[shortLang] !== undefined) return dict[shortLang];
  if (dict['en-US'] !== undefined) return dict['en-US'];
  if (dict['ja-JP'] !== undefined) return dict['ja-JP'];
  return '';
}
